<?php
class SchoolReportRenderer {
    private static function e($v):string{return htmlspecialchars((string)($v??'Not available'),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private static function display($v):string {if($v===null)return 'Not available';if(is_float($v))return rtrim(rtrim(number_format($v,2,'.',''),'0'),'.');return (string)$v;}
    public static function svg(array $chart):string {
        $colors=['#476f91','#4d8e7c','#bb9450','#8e76a6','#b5757d','#6b8b9e','#8d9c70','#8c91ac'];$labels=$chart['labels'];$values=array_map(static fn($v)=>max(0,(float)$v),$chart['values']);$total=array_sum($values);$title=self::e($chart['title']);
        if(!$total)return '<svg xmlns="http://www.w3.org/2000/svg" width="420" height="170" viewBox="0 0 420 170"><text x="20" y="85" font-family="DejaVu Sans" font-size="12" fill="#6c7f8d">No matching data</text></svg>';
        $svgHeight=max(190,count($labels)*21+25);$svg='<svg xmlns="http://www.w3.org/2000/svg" width="420" height="'.$svgHeight.'" viewBox="0 0 420 '.$svgHeight.'"><title>'.$title.'</title>';
        if($chart['kind']==='pie'){$angle=-M_PI/2;$cx=88;$cy=90;$radius=66;foreach($values as $i=>$v){if(!$v)continue;$next=$angle+$v/$total*2*M_PI;$color=$colors[$i%count($colors)];if($v===$total){$svg.='<circle cx="88" cy="90" r="66" fill="'.$color.'"/>';}else{$x1=$cx+cos($angle)*$radius;$y1=$cy+sin($angle)*$radius;$x2=$cx+cos($next)*$radius;$y2=$cy+sin($next)*$radius;$svg.='<path d="M '.$cx.' '.$cy.' L '.$x1.' '.$y1.' A '.$radius.' '.$radius.' 0 '.(($next-$angle)>M_PI?'1':'0').' 1 '.$x2.' '.$y2.' Z" fill="'.$color.'"/>';}$angle=$next;}
            foreach($labels as $i=>$label){$y=22+$i*20;$svg.='<rect x="170" y="'.($y-9).'" width="9" height="9" fill="'.$colors[$i%count($colors)].'"/><text x="186" y="'.$y.'" font-family="DejaVu Sans" font-size="9" fill="#263e50">'.self::e(mb_strimwidth((string)$label,0,25,'...')).' ('.self::e($values[$i]).')</text>';}
        }else{$max=max($values);$shown=count($labels);$height=18;for($i=0;$i<$shown;$i++){$y=18+$i*21;$width=$max?$values[$i]/$max*220:0;$svg.='<text x="2" y="'.($y+10).'" font-family="DejaVu Sans" font-size="9" fill="#344d60">'.self::e(mb_strimwidth((string)$labels[$i],0,22,'...')).'</text><rect x="135" y="'.$y.'" width="'.$width.'" height="'.$height.'" fill="'.$colors[$i%count($colors)].'"/><text x="'.(140+$width).'" y="'.($y+11).'" font-family="DejaVu Sans" font-size="9" fill="#344d60">'.self::e($values[$i]).'</text>';}}
        return $svg.'</svg>';
    }
    public static function html(array $p):string {
        $school="St. Rita's College of Balingasag";$logo=__DIR__.'/../../assets/images/logo.jpg';$logoData=is_file($logo)?'data:image/jpeg;base64,'.base64_encode(file_get_contents($logo)):'';
        $css='@page{size:A4 portrait;margin:13mm 12mm 17mm}*{box-sizing:border-box}body{margin:0;padding:0;color:#223a4c;background:#fff;font-family:"DejaVu Sans",Arial,sans-serif;font-size:9pt;line-height:1.4}body{width:186mm;margin:0 auto}.rp-header{text-align:center;border-bottom:2px solid #27485e;padding:0 0 9px;margin:0 0 12px;page-break-inside:avoid}.rp-logo{width:43px;height:43px;float:left}.rp-header h1{font-size:13pt;margin:1px 45px 2px;color:#203e54}.rp-header p{font-size:8pt;margin:1px}.rp-header h2{font-size:12pt;text-transform:uppercase;margin:10px 0 3px;color:#203e54}.rp-meta{width:100%;border-collapse:collapse;margin-bottom:12px}.rp-meta td{width:50%;border:0;padding:3px 7px;font-size:8pt;vertical-align:top;word-wrap:break-word}.rp-meta b{color:#334f63}h3{font-size:9.5pt;margin:13px 0 6px;color:#2a4c65}.rp-summary{width:100%;border-collapse:collapse;table-layout:fixed;margin:5px 0 14px}.rp-summary td{border:1px solid #d0dce5;background:#f4f7fa;text-align:center;vertical-align:top;padding:8px 5px;font-size:8pt}.rp-summary strong{display:block;font-size:14pt;margin-top:4px;color:#203e54}.rp-data{border-collapse:collapse;table-layout:fixed;width:100%;margin-bottom:12px}.rp-data th{background:#203e54;color:#fff;font-size:8pt;text-align:left;padding:6px 5px;font-weight:bold}.rp-data td{font-size:7.5pt;vertical-align:top;word-wrap:break-word;border-bottom:1px solid #e1e8ed;padding:5px}.rp-data tbody tr:nth-child(even){background:#f1f4f7}.rp-data thead{display:table-header-group;page-break-inside:avoid;page-break-after:avoid}.rp-data tr{page-break-inside:avoid}.rp-data th,.rp-data td{overflow-wrap:anywhere}.rp-table-title{page-break-after:avoid}.rp-block{margin-bottom:12px}.rp-chart-grid{width:100%;border-collapse:collapse;table-layout:fixed}.rp-chart-grid td{width:50%;vertical-align:top;padding:6px 8px;border:1px solid #e1e8ed}.rp-chart-grid img{display:block;width:100%;height:auto}.rp-chart-grid h3{font-size:8.5pt;margin:0 0 5px}.rp-chart-block{page-break-inside:avoid}.rp-prose{font-size:8pt;color:#536978}.rp-prose ul{margin:4px 0 8px;padding-left:16px}.rp-prose li{margin-bottom:4px}.rp-signatures{width:100%;border-collapse:collapse;margin-top:25px;page-break-inside:avoid}.rp-signatures td{width:33.33%;text-align:center;border:0;padding:4px 10px;font-size:8pt}.rp-signature-line{border-bottom:1px solid #71818c;min-height:30px;padding-top:18px;margin-bottom:5px}.rp-note{font-size:7.5pt;color:#657987;margin:5px 0 9px}.rp-footer{font-size:7pt;color:#7b8d9b}.rp-page{background:#fff;width:210mm;height:297mm;padding:13mm 12mm 17mm;position:relative;overflow:hidden;page-break-after:always;break-after:page}.rp-page:last-child{page-break-after:auto;break-after:auto}.rp-page-content{height:267mm;overflow:hidden}.rp-page-footer{position:absolute;bottom:7mm;left:12mm;right:12mm;font-size:7pt;color:#718797;border-top:1px solid #e1e8ed;padding-top:3mm}.rp-page-footer span{float:right}@media screen{body{background:#e9eef3;width:auto;padding:15px}.rp-source{background:#fff;width:210mm;min-height:297mm;margin:0 auto;padding:13mm 12mm 17mm;box-shadow:0 1px 8px #243f5820}.rp-page{margin:0 auto 15px;box-shadow:0 1px 8px #243f5820}}@media print{html,body{width:auto;background:#fff;margin:0;padding:0}.rp-source{padding:0}.rp-screen-only,nav,aside,button,.filters,.actions{display:none!important}.rp-page{margin:0;box-shadow:none}}';
        $html='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'.self::e($p['title']).'</title><style>'.$css.'</style></head><body><main class="rp-source"><header class="rp-header">'.($logoData?'<img class="rp-logo" src="'.$logoData.'" alt="School guidance seal">':'').'<h1>'.self::e($school).'</h1><p>Guidance and Counseling Office</p><h2>'.self::e($p['title']).'</h2><p>Academic year: '.self::e($p['filters']['school_year']?:'All recorded school years').'</p></header>';
        $meta=['Report ID'=>$p['report_id'],'Date generated'=>$p['generated_at']]+$p['filter_labels'];$html.='<section class="rp-block"><table class="rp-meta">';$i=0;foreach($meta as $label=>$value){if($i%2===0)$html.='<tr>';$html.='<td><b>'.self::e($label).':</b> '.self::e($value).'</td>';if($i%2===1)$html.='</tr>';$i++;}if($i%2)$html.='<td></td></tr>';$html.='</table></section><section class="rp-block"><h3>Summary statistics</h3><table class="rp-summary">';$i=0;foreach(($p['kind']==='examinees'?array_intersect_key($p['metrics'],array_flip(['Total examinees','Passed','Failed','Passing rate (%)'])):$p['metrics']) as $label=>$value){if($i%4===0)$html.='<tr>';$html.='<td>'.self::e($label).'<strong>'.self::e(self::display($value)).'</strong></td>';if($i%4===3)$html.='</tr>';$i++;}if($i%4)$html.=str_repeat('<td></td>',4-$i%4).'</tr>';$html.='</table></section>';
        $beforeAnalysis=$html;$html='';
        foreach(array_chunk($p['charts'],2) as $pair){$html.='<section class="rp-block rp-chart-block"><table class="rp-chart-grid"><tr>';foreach($pair as $chart)$html.='<td><h3>'.self::e($chart['title']).'</h3><img alt="'.self::e($chart['title']).'" src="data:image/svg+xml;base64,'.base64_encode(self::svg($chart)).'"></td>';if(count($pair)===1)$html.='<td></td>';$html.='</tr></table></section>';}
        foreach([['Summary findings',$p['findings']],['Recommendations',$p['recommendations']]] as [$heading,$items]){if(!$items)continue;$html.='<section class="rp-block rp-prose"><h3>'.self::e($heading).'</h3><ul>';foreach($items as $text)$html.='<li>'.self::e($text).'</li>';$html.='</ul></section>';}
        $analysis=$html;$html=$beforeAnalysis;if($p['kind']!=='examinees')$html.=$analysis;
        // Main examinee list is kept compact like the supplied school-report reference.
        $tables=$p['tables'];if($p['kind']==='examinees')usort($tables,static fn($a,$b)=>(str_starts_with($b['title'],'List of ')?1:0)<=>(str_starts_with($a['title'],'List of ')?1:0));
        foreach($tables as $table){$html.='<section class="rp-table-section"><h3 class="rp-table-title">'.self::e($table['title']).'</h3><table class="rp-data"><colgroup>';foreach(self::widths($table['columns']) as $w)$html.='<col style="width:'.$w.'%">';$html.='</colgroup><thead><tr>';foreach($table['columns'] as $j=>$label)$html.='<th style="width:'.self::widths($table['columns'])[$j].'%">'.self::e($label).'</th>';$html.='</tr></thead><tbody>';if(!$table['rows'])$html.='<tr><td colspan="'.count($table['columns']).'">No matching records.</td></tr>';foreach($table['rows'] as $row){$html.='<tr>';foreach($row as $value)$html.='<td>'.self::e(self::display($value)).'</td>';$html.='</tr>';}$html.='</tbody></table></section>';}
        if($p['kind']==='examinees')$html.=$analysis;
        $html.='<section class="rp-block rp-prose"><h3>Report notes</h3><ul>';foreach($p['notes'] as $note)$html.='<li>'.self::e($note).'</li>';$html.='</ul></section><section class="rp-block"><table class="rp-signatures"><tr>';foreach([['Prepared by',$p['prepared_by']],['Verified by',$p['verified_by']],['Approved by',$p['approved_by']]] as [$label,$name])$html.='<td><strong>'.self::e($label).':</strong><div class="rp-signature-line">'.self::e($name).'</div><span>Signature over printed name</span></td>';$html.='</tr></table></section></main></body></html>';return $html;
    }
    private static function widths(array $columns):array {$weights=[];foreach($columns as $c){$name=strtolower($c);$weights[]=str_contains($name,'name')?2.4:(str_contains($name,'classification')||str_contains($name,'examination')||str_contains($name,'email')?2:(in_array($name,['no.','count','total','low','middle','high','sai'],true)?.7:1.2));}$sum=array_sum($weights);return array_map(static fn($w)=>round($w/$sum*100,2),$weights);}
    public static function pdf(array $p):string {
        require_once __DIR__.'/vendor/autoload.php';$options=new \Dompdf\Options();$options->set('defaultMediaType','print');$options->set('isRemoteEnabled',false);$options->set('isPhpEnabled',false);$options->set('isJavascriptEnabled',false);$options->set('defaultFont','DejaVu Sans');$options->set('tempDir',sys_get_temp_dir());$options->set('fontCache',sys_get_temp_dir());$options->set('chroot',__DIR__);
        $html=self::html($p);$start=strpos($html,'@media screen{');$end=strpos($html,'</style>',$start);$html=substr_replace($html,'',$start,$end-$start);
        $pdf=new \Dompdf\Dompdf($options);$pdf->setPaper('A4','portrait');$pdf->loadHtml($html,'UTF-8');$pdf->render();$canvas=$pdf->getCanvas();$font=$pdf->getFontMetrics()->getFont('DejaVu Sans','normal');$canvas->page_text(36,$canvas->get_height()-28,$p['report_id'],$font,6,[.4,.48,.55]);$canvas->page_text($canvas->get_width()-125,$canvas->get_height()-28,'Page {PAGE_NUM} of {PAGE_COUNT}',$font,7,[.4,.48,.55]);return $pdf->output();
    }
    private static function csvCell($value){if($value===null)return 'Not available';if(is_string($value)&&preg_match('/^[\s]*[=+@\-\t\r]/u',$value))return "'".$value;return $value;}
    public static function csv(array $p):string {
        $handle=fopen('php://temp','w+');fwrite($handle,"\xEF\xBB\xBF");$put=static function($row)use($handle){fputcsv($handle,array_map([self::class,'csvCell'],$row));};$put([$p['title']]);$put(['Report ID',$p['report_id']]);$put(['Generated',$p['generated_at']]);foreach($p['filter_labels'] as $key=>$v)$put([$key,$v]);$put([]);$put(['Summary metric','Value']);foreach($p['metrics'] as $key=>$v)$put([$key,$v]);
        foreach($p['tables'] as $table){if($table['detail'])continue;$put([]);$put([$table['title']]);$put($table['columns']);foreach($table['rows'] as $row)$put($row);}
        if(isset($p['export_columns'])){$put([]);$put(['Authorized detailed records']);$put($p['export_columns']);foreach($p['export_rows'] as $row)$put($row);}
        foreach([['Findings',$p['findings']],['Recommendations',$p['recommendations']],['Report notes',$p['notes']]] as [$title,$items]){$put([]);$put([$title]);foreach($items as $text)$put([$text]);}$put(['Prepared by',$p['prepared_by']]);$put(['Verified by',$p['verified_by']]);$put(['Approved by',$p['approved_by']]);rewind($handle);$result=stream_get_contents($handle);fclose($handle);return $result;
    }
    private static function xml($v):string{return htmlspecialchars(preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/','',(string)$v),ENT_XML1|ENT_QUOTES,'UTF-8');}
    private static function column(int $n):string{$s='';while($n>0){$n--;$s=chr(65+$n%26).$s;$n=intdiv($n,26);}return $s;}
    private static function sheet(array $rows,int $freeze,bool $records=false):string {
        $max=1;foreach($rows as $r)$max=max($max,count($r['cells']));$last=self::column($max);$xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr><pageSetUpPr fitToPage="1"/></sheetPr><sheetViews><sheetView workbookViewId="0" showGridLines="0"><pane ySplit="'.$freeze.'" topLeftCell="A'.($freeze+1).'" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>';for($i=1;$i<=$max;$i++)$xml.='<col min="'.$i.'" max="'.$i.'" width="'.($records?($i===2?30:($i===1?22:19)):($i===1?37:24)).'" customWidth="1"/>';$xml.='</cols><sheetData>';
        foreach($rows as $i=>$row){$number=$i+1;$xml.='<row r="'.$number.'">';foreach($row['cells'] as $j=>$value){$style=$row['style']??0;$ref=self::column($j+1).$number;if((is_int($value)||is_float($value))&&is_finite((float)$value))$xml.='<c r="'.$ref.'" s="'.$style.'"><v>'.$value.'</v></c>';else $xml.='<c r="'.$ref.'" s="'.$style.'" t="inlineStr"><is><t xml:space="preserve">'.self::xml($value===null?'Not available':$value).'</t></is></c>';}$xml.='</row>';}
        $xml.='</sheetData>';if($records&&count($rows)>7)$xml.='<autoFilter ref="A7:'.$last.count($rows).'"/>';$xml.='<printOptions horizontalCentered="1"/><pageMargins left="0.3" right="0.3" top="0.45" bottom="0.5" header="0.15" footer="0.2"/><pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/><headerFooter><oddFooter>&amp;LGuidance Office&amp;CPage &amp;P of &amp;N</oddFooter></headerFooter></worksheet>';return $xml;
    }
    public static function xlsx(array $p):string {
        $summary=[];$add=static function($cells,$style=0)use(&$summary){$summary[]=['cells'=>$cells,'style'=>$style];};$add(["St. Rita's College of Balingasag"],2);$add([$p['title']],2);$add(['Generated',$p['generated_at']]);$add(['Report ID',$p['report_id']]);foreach($p['filter_labels'] as $k=>$v)$add([$k,$v]);$add([]);$add(['Summary metric','Value'],1);foreach($p['metrics'] as $k=>$v)$add([$k,$v]);foreach($p['tables'] as $t){if($t['detail'])continue;$add([]);$add([$t['title']],2);$add($t['columns'],1);foreach($t['rows'] as $r)$add($r);}
        foreach([['Findings',$p['findings']],['Recommendations',$p['recommendations']],['Report notes',$p['notes']]] as [$heading,$items]){$add([]);$add([$heading],2);foreach($items as $item)$add([$item]);}$add([]);$add(['Prepared by',$p['prepared_by']]);$add(['Verified by',$p['verified_by']]);$add(['Approved by',$p['approved_by']]);
        $sheets=[['name'=>'Summary','rows'=>$summary,'freeze'=>2,'records'=>false]];
        if(isset($p['export_columns'])){$r=[['cells'=>["St. Rita's College of Balingasag"],'style'=>2],['cells'=>[$p['title']],'style'=>2],['cells'=>['Generated',$p['generated_at']]],['cells'=>['Report ID',$p['report_id']]],['cells'=>['Filters',implode('; ',array_map(static fn($k,$v)=>$k.': '.$v,array_keys($p['filter_labels']),array_values($p['filter_labels'])))]],['cells'=>[]],['cells'=>$p['export_columns'],'style'=>1]];foreach($p['export_rows'] as $i=>$row)$r[]=['cells'=>$row,'style'=>$i%2?3:0];$sheets[]=['name'=>'Records','rows'=>$r,'freeze'=>7,'records'=>true];}
        $tmp=tempnam(sys_get_temp_dir(),'school-xlsx-');$zip=new ZipArchive();try{if($zip->open($tmp,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Could not create the Excel file.');
            $types='<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>';
            $workbook='<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>';$relationships='<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">';
            foreach($sheets as $i=>$sheet){$n=$i+1;$types.='<Override PartName="/xl/worksheets/sheet'.$n.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';$workbook.='<sheet name="'.$sheet['name'].'" sheetId="'.$n.'" r:id="rId'.$n.'"/>';$relationships.='<Relationship Id="rId'.$n.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$n.'.xml"/>';$zip->addFromString('xl/worksheets/sheet'.$n.'.xml',self::sheet($sheet['rows'],$sheet['freeze'],$sheet['records']));}
            $workbook.='</sheets><definedNames>';foreach($sheets as $i=>$sheet)$workbook.='<definedName name="_xlnm.Print_Titles" localSheetId="'.$i.'">\''.$sheet['name'].'\'!$'.$sheet['freeze'].':$'.$sheet['freeze'].'</definedName>';$workbook.='</definedNames></workbook>';$relationships.='<Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>';
            $zip->addFromString('[Content_Types].xml',$types.'</Types>');$zip->addFromString('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');$zip->addFromString('xl/workbook.xml',$workbook);$zip->addFromString('xl/_rels/workbook.xml.rels',$relationships);
            $zip->addFromString('xl/styles.xml','<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="3"><font><sz val="11"/><name val="Calibri"/><color rgb="FF243F53"/></font><font><b/><sz val="11"/><name val="Calibri"/><color rgb="FFFFFFFF"/></font><font><b/><sz val="16"/><name val="Calibri"/><color rgb="FF203E54"/></font></fonts><fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF203E54"/><bgColor indexed="64"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF0F4F7"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="4"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFill="1" applyFont="1" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf><xf numFmtId="0" fontId="2" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="0" fontId="0" fillId="3" borderId="0" xfId="0" applyFill="1" applyAlignment="1"><alignment vertical="top" wrapText="1"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');$zip->close();$bytes=file_get_contents($tmp);if($bytes===false)throw new RuntimeException('Could not read the Excel file.');return $bytes;
        }finally{if(is_file($tmp))unlink($tmp);}
